from pathlib import Path
import base64

def dec(value):
    return base64.b64decode(value).decode('utf-8')

replacements = [
    (
        'backend/src/main/java/com/architecturalthinking/mediaos/spline/SplineAuthoringOverlayRegistryService.java',
        '',
        '',
        'terminal coverage READY semantics',
    ),
    (
        'worker/media-os-local-runner.ps1',
        'JHdvcmtlclBhdGggPSBKb2luLVBhdGggJHdvcmtlckRpciAic3BsaW5lLXdvcmtlci5wczEiCiR3b3JrZXJUZW1wUGF0aCA9IEpvaW4tUGF0aCAkd29ya2VyRGlyICJzcGxpbmUtd29ya2VyLnBzMS5kb3dubG9hZCIKJGxvZ1BhdGggPSBKb2luLVBhdGggJGxvZ0RpciAic3BsaW5lLXdvcmtlci5sb2ci',
        '',
        'runner helper paths',
    ),
    (
        'worker/media-os-local-runner.ps1',
        '',
        '',
        'runner helper sync',
    ),
    (
        'worker/media-os-local-runner.ps1',
        'ICBpZiAoLW5vdCAoVGVzdC1QYXRoICR3b3JrZXJQYXRoKSkgewogICAgdGhyb3cgIkxvY2FsIFJ1bm5lciBzZWxmLXRlc3QgY291bGQgbm90IGZpbmQgdGhlIHdvcmtlci4iCiAgfQogIFdyaXRlLUhvc3QgIk1FRElBX09TX0xPQ0FMX1JVTk5FUl9TRUxGX1RFU1Q6IE9LIg==',
        '',
        'runner helper self-test',
    ),
    (
        'worker/spline-worker.ps1',
        'ZnVuY3Rpb24gQ2FwdHVyZS1TcGxpbmVXaW5kb3dTbmFwc2hvdCB7',
        '',
        'direct helper invocation function',
    ),
    (
        'worker/spline-worker.ps1',
        '',
        '',
        'direct-first overlay execution',
    ),
    (
        'worker/spline-worker.ps1',
        '',
        '',
        'direct overlay metrics guard',
    ),
]

loaded = {}
for path, old_b64, new_b64, label in replacements:
    file_path = Path(path)
    text = loaded.get(path)
    if text is None:
        text = file_path.read_text(encoding='utf-8')
    old = dec(old_b64)
    new = dec(new_b64)
    count = text.count(old)
    if count != 1:
        raise SystemExit(f'Expected exactly one {label} in {path}, found {count}.')
    text = text.replace(old, new)
    loaded[path] = text

for path, text in loaded.items():
    Path(path).write_text(text, encoding='utf-8')

print('Patched:', ', '.join(sorted(loaded)))
